/// <reference lib="webworker" />

// VERSION and PRECACHE are regenerated by scripts/build.js at deploy time,
// stamped from the bytes actually shipped to dist/. The values below are
// placeholders for local/dev use.
//
// Multiplayer twist (same as rabbit-race and penguin-push): this worker does NOT
// take over a page that says it is in a friend room. Swapping the bundle
// mid-shift would reload a player out of the game: see ROOM_ACTIVE below.

const VERSION = 'dev';
const CACHE = `steve-raccoon-${VERSION}`;

const PRECACHE = ['./'];

/** Set by the page while it is in a room; blocks the takeover until it clears. */
let roomActive = false;

self.addEventListener('install', (event) => {
	event.waitUntil(
		caches
			.open(CACHE)
			.then((cache) => cache.addAll(PRECACHE))
			.then(() => {
				// Don't cut in front of a game in progress.
				if (!roomActive) return self.skipWaiting();
				return undefined;
			}),
	);
});

self.addEventListener('activate', (event) => {
	event.waitUntil(
		caches
			.keys()
			.then((keys) =>
				Promise.all(keys.filter((k) => k !== CACHE).map((k) => caches.delete(k))),
			)
			.then(() => self.clients.claim()),
	);
});

self.addEventListener('message', (event) => {
	const data = event.data;
	if (!data || typeof data !== 'object') return;
	if (data.type === 'ROOM_ACTIVE') {
		roomActive = Boolean(data.active);
		// The player just left the room, so a waiting update is now safe to apply.
		if (!roomActive) self.skipWaiting();
	}
});

self.addEventListener('fetch', (event) => {
	const request = event.request;
	if (request.method !== 'GET') return;

	const url = new URL(request.url);
	if (url.origin !== self.location.origin) return;

	// version.json must never come from cache: it is how a client discovers that
	// its own bundle is stale.
	if (url.pathname.endsWith('/version.json')) {
		event.respondWith(fetch(request, { cache: 'no-store' }).catch(() => new Response('{}')));
		return;
	}

	// Page loads ignore the query string: ./?room=ABCD is still the cached
	// ./ (the room code is read by the page, not the server).
	const page = request.mode === 'navigate';
	event.respondWith(
		caches.match(request, { ignoreSearch: page }).then((hit) => {
			if (hit) return hit;
			return fetch(request).then((response) => {
				if (!response.ok || response.type !== 'basic') return response;
				const copy = response.clone();
				caches.open(CACHE).then((cache) => cache.put(request, copy));
				return response;
			});
		}),
	);
});
